<template>
    <section class="review-page" aria-labelledby="review-title"><p class="review-page__eyebrow">ASII-20 · Validación por bioquímico</p><h1 id="review-title">Revisión de resultado</h1><p v-if="message" class="review-page__message" role="status">{{ message }}</p><p v-if="error" class="review-page__error" role="alert">{{ error }}</p><article v-if="result" class="review-page__card"><div class="review-page__summary"><div><span>Resultado</span><strong>{{ result.id }}</strong></div><div><span>Paciente</span><strong>{{ result.patient_code }}</strong></div><div><span>Prueba</span><strong>{{ result.test_code }}</strong></div><div><span>Valor</span><strong>{{ result.value }} {{ result.unit }}</strong></div><div><span>Estado</span><strong>{{ result.status }}</strong></div></div><label v-if="result.status === 'pendiente_revision'">Motivo de rechazo<input v-model="reason" placeholder="Solo se usa para rechazar" /></label><div class="review-page__actions" v-if="result.status === 'pendiente_revision'"><button :disabled="busy" @click="decide('validate')">Validar resultado</button><button class="review-page__reject" :disabled="busy || !reason" @click="decide('reject')">Rechazar</button></div><p v-else>La decisión ya está registrada y no puede repetirse.</p></article></section>
</template>
<script setup>
import { onMounted, ref } from 'vue'; import api from '@/plugins/axios';
const result = ref(null); const reason = ref(''); const error = ref(''); const message = ref(''); const busy = ref(false);
async function load(){ try { const { data }=await api.get('/lab-validation/results'); result.value=data.data.result; } catch(e){ error.value=e.response?.data?.error??'No fue posible cargar la revisión.'; } }
async function decide(action){ busy.value=true; error.value=''; try { const url=`/lab-validation/results/${result.value.id}/${action}`; const payload=action==='reject'?{reason:reason.value}:{}; const {data}=await api.post(url,payload); message.value=data.message; await load(); } catch(e){ error.value=e.response?.data?.error??'La decisión fue rechazada.'; } finally { busy.value=false; } }
onMounted(load);
</script>
<style scoped>.review-page{max-width:850px;margin:auto}.review-page__eyebrow{color:#2563eb;font-weight:700;font-size:.85rem}.review-page h1{margin:.25rem 0 1rem}.review-page__card{padding:1.25rem;background:#fff;border:1px solid #cbd5e1;border-radius:.5rem}.review-page__summary{display:grid;grid-template-columns:repeat(5,1fr);gap:1rem}.review-page__summary span{display:block;color:#64748b;font-size:.8rem}.review-page__summary strong{display:block;margin-top:.25rem}.review-page label{display:grid;gap:.3rem;margin-top:1.5rem;font-weight:600}.review-page input{padding:.6rem;border:1px solid #94a3b8;border-radius:.3rem;font:inherit}.review-page__actions{display:flex;gap:.75rem;margin-top:1.25rem}.review-page button{padding:.65rem 1rem;border:0;border-radius:.3rem;background:#166534;color:white;font-weight:700}.review-page__reject{background:#b91c1c!important}.review-page__message{padding:.7rem;background:#dcfce7;color:#166534}.review-page__error{padding:.7rem;background:#fee2e2;color:#991b1b}@media(max-width:700px){.review-page__summary{grid-template-columns:repeat(2,1fr)}}
</style>
